/* Flashcards app — vanilla JS, no build step.
 * Data: decks/index.json lists the tests; decks/<file>.json holds one test = { key, title, rev, sections: [ { name, cards } ] }
 *       (both generated by tools/import_doc.py). Older single-file cards.json is still read if the index is missing.
 * Progress: localStorage (nf.v1), in-progress session: localStorage (nf.session.v1)
 * Edits: changes made in the app are ops (see core.js) queued per test in localStorage (nf.edits.v1)
 *        and shown on top of the downloaded tests until they are saved.
 * Glossary: glossary/index.json + glossary/<name>.json (generated by tools/build_glossary.py)
 */
(() => {
  'use strict';

  // A setup link (#setup=<token>) must leave the address bar and history at once.
  let setupToken = null;
  if (location.hash.startsWith('#setup=')) { setupToken = location.hash.slice(7); history.replaceState(null, '', location.pathname + location.search); }

  const STORE_KEY = 'nf.v1';
  const SESSION_KEY = 'nf.session.v1';
  const PREFS_KEY = 'nf.prefs.v2';
  const EDITS_KEY = 'nf.edits.v1';      // { deckKey: [op, ...] } not yet saved
  const SAVED_KEY = 'nf.saved.v1';      // { deckKey: deck } last copy this device saved, used while the website catches up
  const GH_KEY = 'nf.gh.v1';            // { token, at } this device's GitHub token (from the setup link)

  const $app = document.getElementById('app');
  const $nav = document.getElementById('nav');
  const $toast = document.getElementById('toast');

  const state = {
    decks: [],
    cards: new Map(),        // id -> card (+ section, deckKey)
    progress: loadJSON(STORE_KEY) || { cards: {}, sessions: [] },
    session: loadJSON(SESSION_KEY) || null,
    prefs: loadJSON(PREFS_KEY) || { deck: null, sectionsByDeck: {}, order: 'ordered', scope: 'all', mode: 'rounds' },
    view: 'home',
    browseQuery: '',
    base: [],                // tests as downloaded (before this device's unsaved edits)
    pending: loadJSON(EDITS_KEY) || {},
    editMode: false,         // Browse shows edit controls
    browseOpen: new Set(),   // Browse cards the user expanded (kept across re-renders)
  };

  // ------------------------------------------------------------ utilities
  function loadJSON(k) { try { return JSON.parse(localStorage.getItem(k)); } catch { return null; } }
  function saveJSON(k, v) { try { if (v == null) localStorage.removeItem(k); else localStorage.setItem(k, JSON.stringify(v)); } catch (e) { toast('Could not save (storage full?)'); } }
  function saveProgress() { saveJSON(STORE_KEY, state.progress); }
  function saveSession() { saveJSON(SESSION_KEY, state.session); }
  function savePrefs() { saveJSON(PREFS_KEY, state.prefs); }
  function esc(s) { return String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])); }
  function h(strings, ...vals) { return strings.reduce((out, s, i) => out + s + (i < vals.length ? vals[i] : ''), ''); }
  function shuffle(a) { const r = a.slice(); for (let i = r.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [r[i], r[j]] = [r[j], r[i]]; } return r; }
  function pct(n, d) { return d ? Math.round(100 * n / d) : 0; }
  function fmtDate(ts) { const d = new Date(ts); return d.toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) + ' ' + d.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }); }
  let toastTimer;
  function toast(msg, action) {
    $toast.textContent = msg;
    if (action) {
      const b = document.createElement('button'); b.className = 'toast-act'; b.textContent = action.label;
      b.onclick = () => { $toast.classList.remove('show'); action.run(); };
      $toast.append(' ', b);
    }
    $toast.classList.add('show'); clearTimeout(toastTimer);
    toastTimer = setTimeout(() => $toast.classList.remove('show'), action ? 6000 : 2200);
  }

  function rec(id) { return state.progress.cards[id] || null; }
  function statusOf(id) { const r = rec(id); return r ? r.status : null; }
  function isMastered(id) { return statusOf(id) === 'yes'; }

  // ------------------------------------------------------------ deck loading
  async function loadDecks() {
    const data = await fetchDecks();
    state.index = new Map((data.index || []).map(e => [e.key, e]));
    setBase(data.decks || [{ key: 'single', title: data.title || 'Flashcards', generatedAt: data.generatedAt, cardCount: data.cardCount, sections: data.sections }]);
  }
  function setBase(decks) {
    const saved = loadJSON(SAVED_KEY) || {};
    state.base = decks.map(d => NFCore.newerDeck(d, saved[d.key]));
    // forget saved copies the website has caught up with
    const keep = {}; for (const d of decks) if (saved[d.key] && NFCore.newerDeck(d, saved[d.key]) !== d) keep[d.key] = saved[d.key];
    if (Object.keys(keep).length !== Object.keys(saved).length) saveJSON(SAVED_KEY, Object.keys(keep).length ? keep : null);
    rebuild();
  }
  // the tests as shown = downloaded tests + this device's unsaved ops
  function rebuild() {
    state.decks = state.base.map(d => (state.pending[d.key] || []).length ? NFCore.applyOps(d, state.pending[d.key]).deck : d);
    state.cards.clear();
    for (const d of state.decks) for (const s of d.sections) for (const c of s.cards) state.cards.set(c.id, { ...c, section: s.name, sectionKey: sKey(s), sectionLabel: sLabel(d, s), group: s.group || '', deckKey: d.key, deckTitle: d.title });
    if (!state.decks.some(d => d.key === state.prefs.deck)) state.prefs.deck = state.decks[0].key;
    state.prefs.knownByDeck = state.prefs.knownByDeck || {};
    for (const d of state.decks) {
      const names = d.sections.map(sKey);
      const known = state.prefs.knownByDeck[d.key];
      const sel = state.prefs.sectionsByDeck[d.key];
      let next = sel && sel.some(n => names.includes(n)) ? sel.filter(n => names.includes(n)) : names.slice();
      if (known) next = next.concat(names.filter(n => !known.includes(n) && !next.includes(n))); // new or renamed sections start selected
      state.prefs.sectionsByDeck[d.key] = next;
      state.prefs.knownByDeck[d.key] = names;
    }
    document.title = state.decks.length === 1 ? state.decks[0].title : 'Flashcards';
    if (state.session) {
      const pruned = NFCore.pruneSession(state.session, id => state.cards.has(id));
      if (pruned !== state.session) { state.session = pruned; saveSession(); }
    }
  }
  // decks/index.json + one file per test; falls back to the old single cards.json
  async function fetchDecks() {
    const res = await fetch('decks/index.json', { cache: 'no-cache' });
    if (res.ok) {
      const index = await res.json();
      const decks = await Promise.all((index.decks || []).map(async (e) => {
        const r = await fetch('decks/' + encodeURIComponent(e.file), { cache: 'no-cache' });
        if (!r.ok) throw new Error('decks/' + e.file + ' ' + r.status);
        return r.json();
      }));
      return { decks, index: index.decks || [] };
    }
    const legacy = await fetch('cards.json', { cache: 'no-cache' });
    if (!legacy.ok) throw new Error('decks/index.json ' + res.status);
    return legacy.json();
  }
  function deck() { return state.decks.find(d => d.key === state.prefs.deck) || state.decks[0]; }
  function sKey(sec) { return sec.group ? sec.group + '\u241f' + sec.name : sec.name; }
  function sLabel(d, sec) { return sec.group && sec.name === sec.group && d.sections.some(x => x !== sec && x.group === sec.group) ? 'General' : sec.name; }
  function groupsOf(d) {
    const out = [];
    for (const sec of d.sections) { const g = sec.group || ''; let G = out.find(x => x.name === g); if (!G) out.push(G = { name: g, secs: [] }); G.secs.push(sec); }
    return out;
  }
  function selectedSections() { return state.prefs.sectionsByDeck[deck().key]; }

  // ------------------------------------------------------------ selection
  function selectCards(cfg) {
    const d = state.decks.find(x => x.key === cfg.deck) || deck();
    const secs = new Set(cfg.sections);
    let groups = d.sections.filter(s => secs.has(sKey(s))).map(s => s.cards.map(c => c.id));
    if (cfg.scope === 'unmastered') groups = groups.map(g => g.filter(id => !isMastered(id)));
    if (cfg.scope === 'weakest') groups = [weakestIds(groups.flat(), 20)];
    if (cfg.order === 'section') groups = groups.map(shuffle);
    let ids = groups.flat();
    if (cfg.order === 'shuffled') ids = shuffle(ids);
    return ids;
  }
  function weakestIds(pool, n) {
    const scored = pool.map(id => { const r = rec(id) || { yes: 0, no: 0, last: 0, status: null }; return { id, k: [r.no, r.status === 'no' ? 1 : 0, -r.yes, r.last] }; })
      .filter(x => x.k[0] > 0 || x.k[1] > 0);
    scored.sort((a, b) => b.k[0] - a.k[0] || b.k[1] - a.k[1] || b.k[2] - a.k[2] || b.k[3] - a.k[3]);
    return scored.slice(0, n).map(x => x.id);
  }
  function countFor(cfg) { return selectCards({ ...cfg, order: 'ordered' }).length; }
  function homeCfg() { const p = state.prefs; return { deck: deck().key, sections: selectedSections().slice(), order: p.order, scope: p.scope, mode: p.mode }; }

  // ------------------------------------------------------------ session engine
  function startSession(cfg) {
    const queue = selectCards(cfg);
    if (!queue.length) { toast('No cards match that selection'); return; }
    state.session = {
      config: cfg, queue, index: 0, round: 1, flipped: false,
      answers: [], roundYes: [], roundNo: [], seen: [], firstYes: 0, firstNo: 0,
      startedAt: Date.now(),
    };
    saveSession();
    go('study');
  }
  function currentId() { const s = state.session; return s && s.index < s.queue.length ? s.queue[s.index] : null; }

  function answer(yes) {
    const s = state.session; const id = currentId(); if (!s || !id || !s.flipped) return;
    const prev = rec(id) ? { ...rec(id) } : null;
    const r = prev ? { ...prev } : { status: null, yes: 0, no: 0, last: 0 };
    r.status = yes ? 'yes' : 'no'; r[yes ? 'yes' : 'no'] += 1; r.last = Date.now();
    state.progress.cards[id] = r;
    if (!s.seen.includes(id)) { s.seen.push(id); if (yes) s.firstYes++; else s.firstNo++; }
    const entry = { id, yes, round: s.round, prev, reinserted: null };
    (yes ? s.roundYes : s.roundNo).push(id);
    if (!yes && s.config.mode === 'reinsert') {
      const gap = 4 + Math.floor(Math.random() * 5);
      const pos = Math.min(s.queue.length, s.index + 1 + gap);
      s.queue.splice(pos, 0, id);
      entry.reinserted = pos;
    }
    s.answers.push(entry);
    s.index++; s.flipped = false;
    Cheer.onAnswer(yes);
    saveProgress();
    if (s.index >= s.queue.length) { s.phase = 'summary'; saveSession(); render(); return; }
    saveSession(); render();
  }
  function undo() {
    const s = state.session; if (!s || !s.answers.length) return;
    const e = s.answers.pop();
    if (e.prev) state.progress.cards[e.id] = e.prev; else delete state.progress.cards[e.id];
    if (e.reinserted != null) s.queue.splice(e.reinserted, 1);
    const pile = e.yes ? s.roundYes : s.roundNo; const i = pile.lastIndexOf(e.id); if (i >= 0) pile.splice(i, 1);
    if (!s.answers.some(a => a.id === e.id)) { const k = s.seen.indexOf(e.id); if (k >= 0) s.seen.splice(k, 1); if (e.yes) s.firstYes--; else s.firstNo--; }
    s.index--; s.flipped = true; s.phase = null;
    saveProgress(); saveSession(); render();
  }
  function nextRound() {
    const s = state.session;
    let q = s.roundNo.slice();
    if (s.config.order !== 'ordered') q = shuffle(q);
    s.queue = q; s.index = 0; s.round++; s.roundYes = []; s.roundNo = []; s.flipped = false; s.phase = null;
    saveSession(); render();
  }
  function endSession(record = true) {
    const s = state.session; if (!s) return;
    if (record && s.seen.length) {
      const d = state.decks.find(x => x.key === s.config.deck);
      state.progress.sessions.push({
        at: s.startedAt, deck: d ? d.title : '', sections: s.config.sections, mode: s.config.mode, order: s.config.order, scope: s.config.scope,
        cards: s.seen.length, yes: s.firstYes, no: s.firstNo, rounds: s.round, secs: Math.round((Date.now() - s.startedAt) / 1000),
      });
      if (state.progress.sessions.length > 200) state.progress.sessions.splice(0, state.progress.sessions.length - 200);
      saveProgress();
    }
    state.session = null; saveSession();
  }

  // ------------------------------------------------------------ stats helpers
  function sectionStats(sec) {
    let y = 0, n = 0, u = 0;
    for (const c of sec.cards) { const st = statusOf(c.id); if (st === 'yes') y++; else if (st === 'no') n++; else u++; }
    return { y, n, u, t: sec.cards.length };
  }
  function deckStats(d) {
    let y = 0, n = 0, u = 0, t = 0;
    for (const s of d.sections) { const r = sectionStats(s); y += r.y; n += r.n; u += r.u; t += r.t; }
    return { y, n, u, t };
  }
  function barHtml(st, tall) {
    return h`<div class="bar${tall ? ' tall' : ''}"><div class="y" style="width:${pct(st.y, st.t)}%"></div><div class="n" style="width:${pct(st.n, st.t)}%"></div></div>`;
  }
  function deckPicker() {
    if (state.decks.length < 2) return '';
    return h`<div class="field" style="margin-top:0"><label class="lbl">Test</label><div class="chips">${state.decks.map(d => { const s = deckStats(d); return h`<button class="chip ${d.key === deck().key ? 'on' : ''}" data-deck="${esc(d.key)}">${esc(d.title)} <span class="cnt">${s.y}/${s.t}</span></button>`; }).join('')}</div></div>`;
  }
  function bindDeckPicker(rerender) {
    $app.querySelectorAll('[data-deck]').forEach(b => b.onclick = () => { state.prefs.deck = b.dataset.deck; savePrefs(); rerender(); });
  }

  // ------------------------------------------------------------ routing
  function go(view) { state.view = view; location.hash = view === 'home' ? '' : view; render(); }
  window.addEventListener('hashchange', () => {
    if (location.hash.startsWith('#setup=')) { const raw = location.hash.slice(7); history.replaceState(null, '', location.pathname + location.search); Saver.useSetupToken(raw); return; }
    const v = (location.hash || '#home').slice(1).split('=')[0] || 'home';
    if (v === 'sync' && location.hash.startsWith('#sync=')) { handleIncomingSync(location.hash.slice(6)); return; }
    if (v === 'study' && !state.session) { state.view = 'home'; render(); return; }
    state.view = ['home', 'study', 'stats', 'browse', 'sync'].includes(v) ? v : 'home'; render();
  });

  // ------------------------------------------------------------ render
  function render() {
    document.body.classList.toggle('studying', state.view === 'study');
    for (const a of $nav.querySelectorAll('a')) a.classList.toggle('active', a.dataset.view === state.view);
    window.scrollTo(0, 0);
    switch (state.view) {
      case 'study': return state.session && state.session.phase === 'summary' ? renderSummary() : renderStudy();
      case 'stats': return renderStats();
      case 'browse': return renderBrowse();
      case 'sync': return renderSync();
      default: return renderHome();
    }
  }

  // ---- home
  function renderHome() {
    const d = deck(); const p = state.prefs; const st = deckStats(d);
    const cfg = homeCfg();
    const count = countFor(cfg);
    const resume = state.session;
    const sel = selectedSections();
    const orderHint = { ordered: 'Cards come in the order they appear in the doc.', section: 'Sections stay in order; cards are shuffled inside each section.', shuffled: 'Everything mixed together.' }[p.order];
    $app.innerHTML = h`
      <h1>${esc(d.title)}</h1>
      <p class="sub">${d.cardCount} cards · ${d.sections.length} sections · mastered ${st.y}/${st.t} (${pct(st.y, st.t)}%)</p>
      ${barHtml(st, true)}
      <div class="legend"><span class="ly"><i></i>Got it ${st.y}</span><span class="ln"><i></i>Still learning ${st.n}</span><span class="lu"><i></i>Not seen ${st.u}</span></div>

      ${resume ? h`<div class="panel" style="margin-top:16px">
          <div class="row"><div><b>Session in progress</b><div class="hint">${esc(state.cards.get(resume.queue[0])?.deckTitle || '')} · Round ${resume.round} · card ${Math.min(resume.index + 1, resume.queue.length)} of ${resume.queue.length}</div></div>
          <div class="spacer"></div><button class="btn primary" data-act="resume">Continue</button><button class="btn" data-act="discard">Discard</button></div></div>` : ''}

      <div class="panel" style="margin-top:16px">
        ${deckPicker()}
        ${Glossary.has(d.key) ? h`<div class="field"><label class="lbl">Glossary terms</label>
          <div class="seg" data-act="gl-pref"><button class="${Glossary.enabled() ? 'on' : ''}" data-val="on">Underline</button><button class="${Glossary.enabled() ? '' : 'on'}" data-val="off">Off</button></div>
          <div class="hint">${Glossary.enabled() ? 'Tap an underlined term on a card to see its definition.' : 'Terms are not underlined.'}</div></div>` : ''}
        <div class="field"><label class="lbl">Sections <span class="hint" style="display:inline;text-transform:none;letter-spacing:0;font-weight:500">· <button class="link" data-act="all">All</button> · <button class="link" data-act="none">None</button></span></label>
          ${groupsOf(d).map(G => h`<div class="grp">${G.name ? h`<button class="grp-name" data-grp="${esc(G.name)}" title="Toggle all in ${esc(G.name)}">${esc(G.name)}</button>` : ''}
            <div class="chips">${G.secs.map(sec => { const ss = sectionStats(sec); const k = sKey(sec); return h`<button class="chip ${sel.includes(k) ? 'on' : ''}" data-sec="${esc(k)}">${esc(sLabel(d, sec))} <span class="cnt">${ss.y}/${ss.t}</span></button>`; }).join('')}</div></div>`).join('')}
        </div>
        <div class="field"><label class="lbl">Which cards</label>
          <div class="seg" data-pref="scope">
            <button class="${p.scope === 'all' ? 'on' : ''}" data-val="all">All</button>
            <button class="${p.scope === 'unmastered' ? 'on' : ''}" data-val="unmastered">Not yet mastered</button>
            <button class="${p.scope === 'weakest' ? 'on' : ''}" data-val="weakest">Weakest 20</button>
          </div></div>
        <div class="field"><label class="lbl">Order</label>
          <div class="seg" data-pref="order">
            <button class="${p.order === 'ordered' ? 'on' : ''}" data-val="ordered">In order</button>
            <button class="${p.order === 'section' ? 'on' : ''}" data-val="section">Shuffle within section</button>
            <button class="${p.order === 'shuffled' ? 'on' : ''}" data-val="shuffled">Shuffle all</button>
          </div><div class="hint">${orderHint}</div></div>
        <div class="field"><label class="lbl">When I miss a card</label>
          <div class="seg" data-pref="mode">
            <button class="${p.mode === 'rounds' ? 'on' : ''}" data-val="rounds">Rounds</button>
            <button class="${p.mode === 'reinsert' ? 'on' : ''}" data-val="reinsert">Bring it back soon</button>
          </div>
          <div class="hint">${p.mode === 'rounds' ? 'Finish the deck, then repeat only the missed cards, round after round, until none are left.' : 'A missed card comes back 4–8 cards later in the same pass. The session ends when every card has been answered "Got it".'}</div>
        </div>
        <button class="btn primary big" data-act="start" ${count ? '' : 'disabled'}>Study ${count} card${count === 1 ? '' : 's'}</button>
      </div>
      ${Cheer.pillHtml()}
      <p class="hint kbd-only">Keyboard: <span class="kbd">Space</span> flip · <span class="kbd">→</span> or <span class="kbd">Y</span> got it · <span class="kbd">←</span> or <span class="kbd">N</span> still learning · <span class="kbd">U</span> undo</p>
      <p class="hint">Deck updated ${d.generatedAt ? fmtDate(d.generatedAt) : '—'}</p>`;

    bindDeckPicker(renderHome);
    Cheer.bind($app);
    $app.querySelectorAll('[data-act=gl-pref] button').forEach(b => b.onclick = () => { state.prefs.glossary = b.dataset.val === 'on'; savePrefs(); renderHome(); });
    $app.querySelectorAll('.chip[data-sec]').forEach(b => b.onclick = () => {
      const n = b.dataset.sec; const i = sel.indexOf(n);
      if (i >= 0) sel.splice(i, 1); else sel.push(n);
      savePrefs(); renderHome();
    });
    $app.querySelectorAll('.seg[data-pref] button').forEach(b => b.onclick = () => { p[b.parentElement.dataset.pref] = b.dataset.val; savePrefs(); renderHome(); });
    $app.querySelectorAll('[data-grp]').forEach(b => b.onclick = () => {
      const keys = d.sections.filter(sec => (sec.group || '') === b.dataset.grp).map(sKey);
      const allOn = keys.every(k => sel.includes(k));
      p.sectionsByDeck[d.key] = allOn ? sel.filter(k => !keys.includes(k)) : [...new Set([...sel, ...keys])];
      savePrefs(); renderHome();
    });
    $app.querySelector('[data-act=all]').onclick = () => { p.sectionsByDeck[d.key] = d.sections.map(sKey); savePrefs(); renderHome(); };
    $app.querySelector('[data-act=none]').onclick = () => { p.sectionsByDeck[d.key] = []; savePrefs(); renderHome(); };
    $app.querySelector('[data-act=start]').onclick = () => { if (state.session) endSession(true); startSession(homeCfg()); };
    const r = $app.querySelector('[data-act=resume]'); if (r) r.onclick = () => go('study');
    const dsc = $app.querySelector('[data-act=discard]'); if (dsc) dsc.onclick = () => { if (confirm('Discard the in-progress session? Answers already given are kept in your stats.')) { endSession(true); renderHome(); } };
  }

  // ---- study
  let touch = null;
  function renderStudy() {
    const s = state.session; const id = currentId();
    if (!s || !id) { state.view = 'home'; return renderHome(); }
    const c = state.cards.get(id);
    const total = s.queue.length; const done = s.index;
    const remaining = s.config.mode === 'reinsert' ? new Set(s.queue.slice(s.index)).size : total - done;
    const kicker = [c.group, c.sectionLabel !== c.group || !c.group ? c.sectionLabel : '', c.label].filter(Boolean).map(esc).join(' · ');
    $app.innerHTML = h`
      <div class="study">
        <div class="study-top">
          <button class="btn small" data-act="end">End</button>
          <div class="prog"><div class="txt"><span>${s.config.mode === 'rounds' ? `Round ${s.round} · ` : ''}${done + 1} / ${total}</span><span>${remaining} left</span></div>
            <div class="bar"><div class="p" style="width:${pct(done, total)}%"></div></div></div>
          <button class="btn small" data-act="undo" ${s.answers.length ? '' : 'disabled'}>Undo</button>
        </div>
        <div class="card ${s.flipped ? 'is-back' : ''} ${c.imagePrompt ? 'img-prompt' : ''}" id="card" data-deck="${esc(c.deckKey)}" tabindex="0" role="button" aria-label="${s.flipped ? 'Answer' : 'Prompt, tap to reveal answer'}">
          <div class="kicker"><span>${kicker}</span><span>${state.decks.length > 1 ? esc(c.deckTitle) : ''}${s.flipped ? h` <button class="icon-btn kicker-edit" data-act="study-edit" aria-label="Edit this card" title="Edit this card">✎</button>` : ''}</span></div>
          ${s.flipped
            ? h`<div class="back"><div class="q">${c.promptHtml || esc(c.prompt)}</div><div class="a">${c.answerHtml || '<i>(no answer)</i>'}</div></div>`
            : h`<div class="front"><div class="prompt">${c.promptHtml || esc(c.prompt)}</div></div><div class="tap-hint">Tap to reveal</div>`}
          <div class="more-fade"></div>
        </div>
        <div class="actions">
          ${s.flipped
            ? h`<button class="btn no" data-act="no">Still learning<span class="k kbd-only">← or N</span></button><button class="btn yes" data-act="yes">Got it<span class="k kbd-only">→ or Y</span></button>`
            : h`<button class="btn primary single" data-act="flip">Show answer<span class="k kbd-only">Space</span></button>`}
        </div>
        <div class="under"><span>${s.roundYes.length} got it · ${s.roundNo.length} still learning</span>${Cheer.current()
          ? h`<span class="cheer-nudge"><button class="cheer-pill" data-act="cheer">${esc(Cheer.current())}</button><button class="cheer-x" data-act="cheer-dismiss" aria-label="Dismiss">×</button></span>`
          : h`<span>${s.flipped ? 'Swipe → got it · ← still learning' : ''}</span>`}</div>
      </div>`;

    const $card = $app.querySelector('#card');
    const $scroll = $card.querySelector('.back, .front');
    const markMore = () => $card.classList.toggle('has-more', $scroll.scrollHeight - $scroll.scrollTop - $scroll.clientHeight > 4);
    $scroll.addEventListener('scroll', markMore, { passive: true }); requestAnimationFrame(markMore);
    $scroll.querySelectorAll('img').forEach(img => img.addEventListener('load', markMore));
    Glossary.decorate();
    const flip = () => { if (s.flipped) return; $card.classList.add('flipping'); setTimeout(() => { s.flipped = true; saveSession(); renderStudy(); }, 150); };
    $card.addEventListener('click', (e) => {
      if (e.target.closest('a')) return;
      if (!s.flipped) { flip(); return; }
      const img = e.target.closest('img'); if (img) openLightbox(img.src);
    });
    const f = $app.querySelector('[data-act=flip]'); if (f) f.onclick = flip;
    const se = $app.querySelector('[data-act=study-edit]'); if (se) se.onclick = (e) => { e.stopPropagation(); Editor.open({ deckKey: c.deckKey, cardId: c.id }); };
    const y = $app.querySelector('[data-act=yes]'); if (y) y.onclick = () => answer(true);
    const n = $app.querySelector('[data-act=no]'); if (n) n.onclick = () => answer(false);
    $app.querySelector('[data-act=undo]').onclick = undo;
    Cheer.bind($app);
    $app.querySelector('[data-act=end]').onclick = () => { if (confirm('End this session? Your answers so far are saved.')) { endSession(true); go('home'); } };

    // swipe (only when flipped)
    $card.addEventListener('touchstart', (e) => { if (!s.flipped || e.touches.length !== 1) return; touch = { x: e.touches[0].clientX, y: e.touches[0].clientY }; }, { passive: true });
    $card.addEventListener('touchmove', (e) => {
      if (!touch) return; const dx = e.touches[0].clientX - touch.x, dy = e.touches[0].clientY - touch.y;
      if (Math.abs(dx) > 12 && Math.abs(dx) > Math.abs(dy) * 1.3) { $card.classList.add('dragging'); $card.style.transform = `translateX(${dx * 0.6}px) rotate(${dx / 40}deg)`; }
    }, { passive: true });
    $card.addEventListener('touchend', (e) => {
      if (!touch) return; const dx = e.changedTouches[0].clientX - touch.x, dy = e.changedTouches[0].clientY - touch.y; touch = null;
      $card.classList.remove('dragging'); $card.style.transform = '';
      if (Math.abs(dx) > 70 && Math.abs(dx) > Math.abs(dy) * 1.3) answer(dx > 0);
    }, { passive: true });
    $card.addEventListener('touchcancel', () => { touch = null; $card.classList.remove('dragging'); $card.style.transform = ''; }, { passive: true });
  }

  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') { if (closeSheet()) return; if (Glossary.isOpen()) { Glossary.close(); return; } if (Editor.isOpen()) { Editor.close(); return; } closeLightbox(); Cheer.close(); return; }
    if (Editor.isOpen()) return;
    if (Glossary.isOpen()) return;
    if (state.view !== 'study' || !state.session) return;
    if (e.target && ['INPUT', 'TEXTAREA'].includes(e.target.tagName)) return;
    const s = state.session; const k = e.key;
    if (s.phase === 'summary') { if (k === 'Enter' || k === ' ') { e.preventDefault(); const b = $app.querySelector('[data-act=next]') || $app.querySelector('[data-act=finish]'); b && b.click(); } return; }
    if (k === ' ' || k === 'Enter') { e.preventDefault(); if (!s.flipped) { s.flipped = true; saveSession(); renderStudy(); } return; }
    if (k === 'ArrowRight' || k === 'y' || k === 'Y') { e.preventDefault(); answer(true); }
    else if (k === 'ArrowLeft' || k === 'n' || k === 'N') { e.preventDefault(); answer(false); }
    else if (k === 'u' || k === 'U' || k === 'Backspace') { e.preventDefault(); undo(); }
  });

  // ---- lightbox
  function openLightbox(src) {
    closeLightbox();
    const el = document.createElement('div'); el.className = 'lightbox'; el.id = 'lightbox';
    el.innerHTML = `<img src="${esc(src)}" alt=""><div class="lb-hint">Tap to close</div>`;
    el.onclick = closeLightbox;
    document.body.appendChild(el);
  }
  function closeLightbox() { const el = document.getElementById('lightbox'); if (el) el.remove(); }

  // ---- summary
  function renderSummary() {
    const s = state.session; const rounds = s.config.mode === 'rounds';
    const missed = s.roundNo; const got = s.roundYes;
    const doneAll = missed.length === 0;
    $app.innerHTML = h`
      <div class="study"><div class="summary">
        <p class="sub">${rounds ? `Round ${s.round} complete` : 'Session complete'}</p>
        <div class="big" style="color:${doneAll ? 'var(--yes)' : 'var(--ink)'}">${doneAll ? '🎉' : pct(got.length, got.length + missed.length) + '%'}</div>
        <h1 style="margin-top:0">${doneAll ? (rounds && s.round > 1 ? 'Every card mastered!' : 'All cards got it!') : `${got.length} got it · ${missed.length} still learning`}</h1>
        ${rounds && !doneAll ? h`<p class="sub">Round ${s.round + 1} will have ${missed.length} card${missed.length === 1 ? '' : 's'}.</p>` : ''}
        ${!rounds ? h`<p class="sub">First pass: ${s.firstYes} of ${s.seen.length} right away.</p>` : ''}
        <div class="row" style="justify-content:center; margin-top:16px">
          ${rounds && !doneAll ? h`<button class="btn primary big" data-act="next">Start round ${s.round + 1}</button>` : ''}
          <button class="btn ${rounds && !doneAll ? '' : 'primary'} big" data-act="finish">Finish</button>
        </div>
        ${Cheer.pillHtml()}
        ${missed.length ? h`<div class="panel pile" style="margin-top:20px"><b>Still learning</b><ul class="list">${missed.map(id => h`<li><span class="dot no"></span>${esc(state.cards.get(id).prompt)}</li>`).join('')}</ul></div>` : ''}
      </div></div>`;
    const nx = $app.querySelector('[data-act=next]'); if (nx) nx.onclick = nextRound;
    Cheer.bind($app);
    $app.querySelector('[data-act=finish]').onclick = () => { endSession(true); go('stats'); };
  }

  // ---- stats
  function renderStats() {
    const d = deck(); const st = deckStats(d);
    const weakest = weakestIds(d.sections.flatMap(s => s.cards.map(c => c.id)), 15);
    const sessions = state.progress.sessions.slice().reverse().filter(x => !x.deck || x.deck === d.title).slice(0, 12);
    $app.innerHTML = h`
      <h1>Stats</h1>
      ${state.decks.length > 1 ? h`<div class="panel">${deckPicker()}</div>` : ''}
      <div class="stat-grid">
        <div class="stat y"><b>${st.y}</b><span>got it</span></div>
        <div class="stat n"><b>${st.n}</b><span>still learning</span></div>
        <div class="stat"><b>${st.u}</b><span>not seen</span></div>
      </div>
      <div class="panel" style="margin-top:14px">
        <div class="row"><b>${esc(d.title)} mastery</b><div class="spacer"></div><span>${pct(st.y, st.t)}%</span></div>
        ${barHtml(st, true)}
      </div>
      <div class="panel"><b>By section</b>
        <ul class="list">${groupsOf(d).map(G => (G.name ? h`<li class="grp-head">${esc(G.name)}</li>` : '') + G.secs.map(s => { const ss = sectionStats(s); return h`<li>
          <div class="sec-row"><span class="name">${esc(sLabel(d, s))}</span><span class="pct">${ss.y}/${ss.t}</span>
            <button class="btn small" data-study-sec="${esc(sKey(s))}" ${ss.y === ss.t ? 'disabled' : ''}>Study ${ss.t - ss.y}</button></div>
          ${barHtml(ss)}</li>`; }).join('')).join('')}</ul>
      </div>
      <div class="panel"><div class="row"><b>Weakest cards</b><div class="spacer"></div>${weakest.length ? h`<button class="btn small primary" data-act="study-weak">Study these ${weakest.length}</button>` : ''}</div>
        ${weakest.length ? h`<ul class="list">${weakest.map(id => { const c = state.cards.get(id); const r = rec(id); return h`<li class="sec-row"><span class="dot ${r.status}"></span><span class="name" style="font-weight:500">${esc(c.prompt)}</span><span class="pct">${r.no}✗ ${r.yes}✓</span></li>`; }).join('')}</ul>` : '<p class="empty">No missed cards yet.</p>'}
      </div>
      <div class="panel"><b>Sessions</b>
        ${sessions.length ? h`<table class="hist"><tr><th>When</th><th>Cards</th><th>First-pass</th><th>Mode</th></tr>
          ${sessions.map(x => h`<tr><td>${fmtDate(x.at)}</td><td>${x.cards}</td><td>${pct(x.yes, x.cards)}% <span style="color:var(--muted)">(${x.yes}/${x.cards})</span></td><td>${x.mode === 'rounds' ? `Rounds ×${x.rounds}` : 'Bring back'}</td></tr>`).join('')}</table>` : '<p class="empty">No sessions yet.</p>'}
      </div>
      <div class="row" style="justify-content:center; margin: 8px 0 20px"><button class="btn danger small" data-act="reset">Reset all progress</button></div>`;
    bindDeckPicker(renderStats);
    const base = () => ({ deck: d.key, order: state.prefs.order, mode: state.prefs.mode });
    $app.querySelectorAll('[data-study-sec]').forEach(b => b.onclick = () => { if (state.session) endSession(true); startSession({ ...base(), sections: [b.dataset.studySec], scope: 'unmastered' }); });
    const w = $app.querySelector('[data-act=study-weak]'); if (w) w.onclick = () => { if (state.session) endSession(true); startSession({ ...base(), sections: d.sections.map(sKey), scope: 'weakest' }); };
    $app.querySelector('[data-act=reset]').onclick = () => { if (confirm('Reset ALL progress and session history on this device? This cannot be undone.')) { state.progress = { cards: {}, sessions: [] }; endSession(false); saveProgress(); renderStats(); toast('Progress reset'); } };
  }

  // ---- browse
  function renderBrowse() {
    const d = deck();
    const edit = state.editMode;
    const q = state.browseQuery.trim().toLowerCase();
    const terms = q.split(/\s+/).filter(Boolean);
    const match = (c) => !terms.length || terms.every(t => (c.prompt + ' ' + stripTags(c.answerHtml) + ' ' + (c.label || '')).toLowerCase().includes(t));
    const hi = (html) => terms.length ? highlight(html, terms) : html;
    let total = 0;
    const secsHtml = d.sections.map(s => {
      const cards = s.cards.filter(match); total += cards.length;
      if (!cards.length && !(edit && !terms.length)) return '';
      const k = sKey(s);
      return h`<h2 class="b-sec">${s.group ? h`<span class="grp-inline">${esc(s.group)} ›</span> ` : ''}${esc(sLabel(d, s))} <span style="color:var(--muted);font-weight:400">${cards.length}</span>
          ${edit ? h`<span class="sec-tools"><button class="btn small" data-add="${esc(k)}">+ Card</button><button class="icon-btn" data-secmenu="${esc(k)}" aria-label="Section options" title="Section options">⋯</button></span>` : ''}</h2>
        <div class="panel" style="padding:4px 16px">
        ${cards.length ? '' : '<p class="hint" style="margin:10px 0">No cards in this section yet.</p>'}
        ${cards.map(c => h`<details class="b-card" data-id="${c.id}" ${terms.length || state.browseOpen.has(c.id) ? 'open' : ''}><summary><span class="dot ${statusOf(c.id) || ''}"></span><span class="p">${hi(c.promptHtml || esc(c.prompt))}</span>${c.label ? h`<span class="tag">${esc(c.label)}</span>` : ''}
            ${edit ? h`<span class="card-tools"><button class="icon-btn" data-edit="${c.id}" aria-label="Edit card" title="Edit">✎</button><button class="icon-btn" data-move="${c.id}" aria-label="Move card" title="Move">↕</button><button class="icon-btn" data-del="${c.id}" aria-label="Delete card" title="Delete">🗑</button></span>` : ''}</summary>
          <div class="ans a">${hi(c.answerHtml || '<i>(no answer)</i>')}
            <div class="row" style="margin-top:10px"><button class="btn small" data-mark="no" data-id="${c.id}">Still learning</button><button class="btn small" data-mark="yes" data-id="${c.id}">Got it</button>${statusOf(c.id) ? h`<button class="btn small ghost" data-mark="clear" data-id="${c.id}">Clear</button>` : ''}</div>
          </div></details>`).join('')}</div>`;
    }).join('');
    $app.innerHTML = h`
      <div class="b-head"><h1>Browse</h1><span class="spacer"></span>
        ${edit ? h`${Edits.chipHtml()}<button class="btn small primary" data-act="edit-done">Done</button>` : h`<button class="btn small" data-act="edit-on">✎ Edit cards</button>`}</div>
      ${state.decks.length > 1 ? h`<div class="panel">${deckPicker()}</div>` : ''}
      <input type="search" id="q" placeholder="Search prompts and answers…" value="${esc(state.browseQuery)}" autocomplete="off">
      <p class="hint">${total} card${total === 1 ? '' : 's'}${terms.length ? ' match' : ''}. ${edit ? 'Tap ✎ to edit a card, 🗑 to delete it, or + Card to add one.' : 'Tap a card to expand.'}</p>
      ${secsHtml || '<p class="empty">Nothing matches.</p>'}
      ${edit && !terms.length ? h`<div class="row" style="margin:18px 0 8px"><button class="btn small" data-act="add-sec">+ Add section</button><button class="btn small" data-act="add-unit">+ Add unit</button></div>` : ''}`;
    bindDeckPicker(renderBrowse);
    const $q = $app.querySelector('#q');
    let timer; $q.addEventListener('input', () => { clearTimeout(timer); timer = setTimeout(() => { const pos = $q.selectionStart; state.browseQuery = $q.value; renderBrowse(); const nq = $app.querySelector('#q'); nq.focus(); try { nq.setSelectionRange(pos, pos); } catch {} }, 180); });
    $app.querySelectorAll('details.b-card').forEach(el => el.addEventListener('toggle', () => { if (el.open) state.browseOpen.add(el.dataset.id); else state.browseOpen.delete(el.dataset.id); }));
    $app.querySelectorAll('[data-mark]').forEach(b => b.onclick = (e) => {
      e.preventDefault(); const id = b.dataset.id; const m = b.dataset.mark;
      if (m === 'clear') delete state.progress.cards[id];
      else { const r = rec(id) || { status: null, yes: 0, no: 0, last: 0 }; r.status = m; r[m] += 1; r.last = Date.now(); state.progress.cards[id] = r; }
      saveProgress(); renderBrowse(); toast(m === 'clear' ? 'Cleared' : m === 'yes' ? 'Marked: got it' : 'Marked: still learning');
    });
    $app.querySelectorAll('.ans img').forEach(img => img.onclick = (e) => { e.preventDefault(); openLightbox(img.src); });
    const on = $app.querySelector('[data-act=edit-on]'); if (on) on.onclick = () => { state.editMode = true; renderBrowse(); };
    const done = $app.querySelector('[data-act=edit-done]'); if (done) done.onclick = () => { state.editMode = false; renderBrowse(); };
    // summary buttons must not toggle the card open/closed
    const tool = (sel, fn) => $app.querySelectorAll(sel).forEach(b => b.onclick = (e) => { e.preventDefault(); e.stopPropagation(); fn(b); });
    tool('[data-edit]', b => Editor.open({ deckKey: d.key, cardId: b.dataset.edit }));
    tool('[data-add]', b => Editor.open({ deckKey: d.key, sec: b.dataset.add }));
    tool('[data-del]', b => Edits.deleteCard(d.key, b.dataset.del));
    tool('[data-move]', b => Regroup.moveCard(d.key, b.dataset.move));
    tool('[data-secmenu]', b => Regroup.sectionMenu(d.key, b.dataset.secmenu));
    const as = $app.querySelector('[data-act=add-sec]'); if (as) as.onclick = () => Regroup.addSection(d.key, null);
    const au = $app.querySelector('[data-act=add-unit]'); if (au) au.onclick = () => Regroup.addUnit(d.key);
    Edits.bindChip($app);
    Glossary.decorate();
  }
  function stripTags(s) { return String(s || '').replace(/<[^>]+>/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>'); }
  function highlight(html, terms) {
    const re = new RegExp('(' + terms.map(t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')).join('|') + ')', 'gi');
    return String(html).split(/(<[^>]+>)/g).map(part => part.startsWith('<') ? part : part.replace(re, '<mark class="hit">$1</mark>')).join('');
  }

  // ---- sync
  async function encodeProgress() {
    const compact = { v: 1, c: {}, s: state.progress.sessions };
    for (const [id, r] of Object.entries(state.progress.cards)) compact.c[id] = [r.status === 'yes' ? 1 : r.status === 'no' ? 2 : 0, r.yes, r.no, r.last];
    const bytes = new TextEncoder().encode(JSON.stringify(compact));
    if (typeof CompressionStream === 'function') {
      try {
        const cs = new CompressionStream('deflate-raw');
        const w = cs.writable.getWriter(); w.write(bytes); w.close();
        const buf = await new Response(cs.readable).arrayBuffer();
        return 'z1.' + b64url(new Uint8Array(buf));
      } catch { /* fall through */ }
    }
    return 'p1.' + b64url(bytes);
  }
  async function decodeProgress(code) {
    code = code.trim();
    const m = code.match(/#sync=([^&\s]+)/); if (m) code = m[1];
    const dot = code.indexOf('.'); const kind = code.slice(0, dot), data = code.slice(dot + 1);
    if (!data || !['z1', 'p1'].includes(kind)) throw new Error('Not a sync code');
    let bytes = unb64url(data);
    if (kind === 'z1') {
      const ds = new DecompressionStream('deflate-raw');
      const w = ds.writable.getWriter(); w.write(bytes); w.close();
      bytes = new Uint8Array(await new Response(ds.readable).arrayBuffer());
    }
    const obj = JSON.parse(new TextDecoder().decode(bytes));
    if (obj.v !== 1) throw new Error('Unknown version');
    const cards = {};
    for (const [id, a] of Object.entries(obj.c || {})) cards[id] = { status: a[0] === 1 ? 'yes' : a[0] === 2 ? 'no' : null, yes: a[1] || 0, no: a[2] || 0, last: a[3] || 0 };
    return { cards, sessions: Array.isArray(obj.s) ? obj.s : [] };
  }
  function b64url(bytes) { let s = ''; for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000)); return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); }
  function unb64url(s) { s = s.replace(/-/g, '+').replace(/_/g, '/'); while (s.length % 4) s += '='; const bin = atob(s); const out = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i); return out; }
  function mergeProgress(incoming, replace) {
    if (replace) { state.progress = incoming; }
    else {
      for (const [id, r] of Object.entries(incoming.cards)) {
        const cur = state.progress.cards[id];
        if (!cur) state.progress.cards[id] = r;
        else state.progress.cards[id] = { status: (r.last > cur.last ? r : cur).status, yes: Math.max(cur.yes, r.yes), no: Math.max(cur.no, r.no), last: Math.max(cur.last, r.last) };
      }
      const seen = new Set(state.progress.sessions.map(s => s.at));
      for (const s of incoming.sessions) if (!seen.has(s.at)) state.progress.sessions.push(s);
      state.progress.sessions.sort((a, b) => a.at - b.at);
    }
    saveProgress();
  }
  async function handleIncomingSync(code) {
    history.replaceState(null, '', location.pathname + '#sync');
    state.view = 'sync';
    try {
      const inc = await decodeProgress(code);
      const n = Object.keys(inc.cards).length;
      if (confirm(`Import progress for ${n} cards from the sync link?\n\nOK = merge with this device (keeps the newest answer per card)\nCancel = do nothing`)) { mergeProgress(inc, false); toast('Progress merged'); }
    } catch (e) { toast('That sync link could not be read'); }
    render();
  }
  function renderSync() {
    let y = 0, n = 0; for (const d of state.decks) { const s = deckStats(d); y += s.y; n += s.n; }
    const pendingN = Edits.count();
    const editPanel = h`<div class="panel">
        <b>Saving card edits</b>
        ${Saver.hasToken()
          ? h`<div class="hint">This device saves edits to the shared cards, so they show up on every device.</div>
             <div class="row" style="margin-top:10px">${Edits.chipHtml()}${pendingN ? '<button class="btn small primary" data-act="save-now">Save now</button>' : ''}<span class="spacer"></span><button class="btn small ghost" data-act="forget">Forget this device</button></div>`
          : h`<div class="hint">${pendingN ? h`<b>${pendingN} change${pendingN === 1 ? '' : 's'}</b> made here ${pendingN === 1 ? 'is' : 'are'} saved on this device only. ` : ''}To save edits for every device, open the setup link Matt sent you, on this device.</div>`}
      </div>`;
    $app.innerHTML = h`
      <h1>Sync devices</h1>
      ${editPanel}
      <p class="sub">Progress is saved in this browser only. To carry it to another device, send yourself the sync link and open it there, or paste the code below.</p>
      <div class="panel">
        <b>This device</b><div class="hint">${y} got it · ${n} still learning · ${state.progress.sessions.length} sessions</div>
        <div class="row" style="margin-top:12px">
          <button class="btn primary" data-act="copy">Copy sync link</button>
          ${navigator.share ? '<button class="btn" data-act="share">Share…</button>' : ''}
          <button class="btn" data-act="show">Show code</button>
        </div>
        <textarea id="out" readonly style="display:none; margin-top:10px" aria-label="Sync code"></textarea>
        <p class="hint">Tip: on Apple devices, copying here and pasting on your iPhone or iPad works through Universal Clipboard. Or text/AirDrop the link to yourself.</p>
      </div>
      <div class="panel">
        <b>Import from another device</b>
        <textarea id="in" placeholder="Paste a sync link or code here" style="margin-top:10px"></textarea>
        <div class="row" style="margin-top:10px">
          <button class="btn primary" data-act="merge">Merge</button>
          <button class="btn" data-act="replace">Replace this device</button>
        </div>
        <p class="hint">Merge keeps the newest answer for each card from either device. Replace overwrites everything here.</p>
      </div>`;
    const $out = $app.querySelector('#out');
    const link = async () => location.origin + location.pathname + '#sync=' + await encodeProgress();
    $app.querySelector('[data-act=copy]').onclick = async () => { const l = await link(); try { await navigator.clipboard.writeText(l); toast('Sync link copied'); } catch { $out.style.display = ''; $out.value = l; $out.select(); toast('Select and copy the text below'); } };
    const sh = $app.querySelector('[data-act=share]'); if (sh) sh.onclick = async () => { const l = await link(); try { await navigator.share({ title: 'Flashcards progress', url: l }); } catch { } };
    $app.querySelector('[data-act=show]').onclick = async () => { $out.style.display = ''; $out.value = await encodeProgress(); };
    const doImport = async (replace) => {
      const v = $app.querySelector('#in').value; if (!v.trim()) { toast('Paste a code first'); return; }
      try { const inc = await decodeProgress(v); if (replace && !confirm('Replace all progress on this device?')) return; mergeProgress(inc, replace); toast(replace ? 'Progress replaced' : 'Progress merged'); renderSync(); }
      catch (e) { toast('Could not read that code'); }
    };
    $app.querySelector('[data-act=merge]').onclick = () => doImport(false);
    Edits.bindChip($app);
    const sv = $app.querySelector('[data-act=save-now]'); if (sv) sv.onclick = () => Saver.flush(true);
    const fg = $app.querySelector('[data-act=forget]'); if (fg) fg.onclick = () => {
      if (!confirm('Stop saving edits from this device? Edits not yet saved stay here. You’ll need a new setup link to turn saving back on.')) return;
      Saver.forget(); renderSync(); toast('This device no longer saves edits');
    };
    $app.querySelector('[data-act=replace]').onclick = () => doImport(true);
  }


  // ------------------------------------------------------------ cheer-up easter egg
  const Cheer = (() => {
    const FALLBACK = { balto: ["Don't worry, Balto believes in you! 💙"], us: ["Don't worry, I believe in you! 💙"] };
    let data = null, loading = null, recentPhotos = [], recentMsgs = [];
    let missStreak = 0, sinceNudge = 0, lastNudgeAt = 0, nudge = null, nudgeTimer = null;

    function load() {
      if (data) return Promise.resolve(data);
      loading = loading || Promise.all([
        fetch('cheer/manifest.json', { cache: 'no-cache' }).then(r => r.ok ? r.json() : { photos: [] }).catch(() => ({ photos: [] })),
        fetch('cheer/messages.json', { cache: 'no-cache' }).then(r => r.ok ? r.json() : FALLBACK).catch(() => FALLBACK),
      ]).then(([m, msgs]) => (data = { photos: m.photos || [], msgs: { ...FALLBACK, ...msgs } }));
      return loading;
    }
    function pick(list, recent, keep) {
      const fresh = list.filter(x => !recent.includes(x));
      const pool = fresh.length ? fresh : list;
      const x = pool[Math.floor(Math.random() * pool.length)];
      recent.push(x); if (recent.length > keep) recent.shift();
      return x;
    }
    function choose() {
      const photo = pick(data.photos, recentPhotos, Math.min(40, Math.max(1, data.photos.length - 1)));
      const list = data.msgs[photo.who] || data.msgs.us;
      return { photo, msg: pick(list, recentMsgs, Math.min(8, list.length - 1)) };
    }
    async function show() {
      await load();
      if (!data.photos.length) { toast('No photos yet 💙'); return; }
      close();
      const { photo, msg } = choose();
      const el = document.createElement('div'); el.className = 'cheer-overlay'; el.id = 'cheer';
      const hearts = Array.from({ length: 9 }, (_, i) => `<span class="cheer-heart" style="left:${6 + i * 11}%; animation-delay:${(i * 0.45).toFixed(2)}s; font-size:${14 + (i * 7) % 16}px">${i % 3 ? '💙' : '🩵'}</span>`).join('');
      el.innerHTML = `<div class="cheer-hearts">${hearts}</div>
        <div class="cheer-card" role="dialog" aria-label="A little encouragement">
          <div class="cheer-frame"><img alt="" src="cheer/${photo.file}"><div class="cheer-spinner">💙</div></div>
          <p class="cheer-msg">${esc(msg)}</p>
          <div class="cheer-actions"><button class="cheer-btn" data-act="another">Another one 💙</button><button class="cheer-btn primary" data-act="close">Back to it ✨</button></div>
        </div>`;
      const img = el.querySelector('img');
      img.onload = () => el.querySelector('.cheer-frame').classList.add('ready');
      img.onerror = () => { el.querySelector('.cheer-frame').classList.add('ready', 'broken'); };
      el.addEventListener('click', (e) => { if (e.target === el) close(); });
      el.querySelector('[data-act=close]').onclick = close;
      el.querySelector('[data-act=another]').onclick = () => show();
      document.body.appendChild(el);
      // warm the cache for the next one
      const nxt = data.photos[Math.floor(Math.random() * data.photos.length)]; if (nxt) { const pre = new Image(); pre.src = 'cheer/' + nxt.file; }
    }
    function close() { const el = document.getElementById('cheer'); if (el) { el.classList.add('closing'); setTimeout(() => el.remove(), 220); } }
    function onAnswer(yes) {
      missStreak = yes ? 0 : missStreak + 1; sinceNudge++;
      if (Date.now() - lastNudgeAt < 4 * 60 * 1000) return;
      if (missStreak >= 3) setNudge('Rough patch? Tap for a smile 💙');
      else if (sinceNudge >= 30) setNudge('Quick smile break? 💙');
    }
    function setNudge(text) {
      lastNudgeAt = Date.now(); missStreak = 0; sinceNudge = 0; nudge = text;
      clearTimeout(nudgeTimer); nudgeTimer = setTimeout(() => { nudge = null; if (state.view === 'study') render(); }, 12000);
    }
    function current() { return nudge; }
    function dismiss() { nudge = null; clearTimeout(nudgeTimer); }
    function pillHtml() { return `<div class="cheer-row"><button class="cheer-pill" data-act="cheer">Feeling discouraged? 💙</button></div>`; }
    function bind(root) { root.querySelectorAll('[data-act=cheer]').forEach(b => b.onclick = (e) => { e.preventDefault(); show(); }); const d = root.querySelector('[data-act=cheer-dismiss]'); if (d) d.onclick = (e) => { e.preventDefault(); dismiss(); render(); }; }
    setTimeout(load, 1500); // fetch quietly after the app is up
    return { show, close, onAnswer, current, pillHtml, bind };
  })();



  // ------------------------------------------------------------ edits (queued ops)
  const Edits = (() => {
    const listeners = [];
    function count(key) { return key ? (state.pending[key] || []).length : Object.values(state.pending).reduce((n, l) => n + l.length, 0); }
    function persist() { for (const k of Object.keys(state.pending)) if (!state.pending[k].length) delete state.pending[k]; saveJSON(EDITS_KEY, state.pending); }
    // record ops for a test, show them at once, and tell the saver
    function add(deckKey, ...ops) {
      const list = state.pending[deckKey] = state.pending[deckKey] || [];
      for (const op of ops) list.push({ ...op, n: NFCore.newId(), at: Date.now() });
      persist(); rebuild(); savePrefs();
      listeners.forEach(fn => fn());
    }
    function deleteCard(deckKey, id) {
      const c = state.cards.get(id); if (!c) return;
      add(deckKey, { t: 'del', id });
      rerender();
      toast('Deleted "' + (c.prompt.length > 40 ? c.prompt.slice(0, 40) + '…' : c.prompt) + '"', { label: 'Undo', run: () => { add(deckKey, { t: 'restore', id }); rerender(); } });
    }
    function rerender(quiet) {
      const y = window.scrollY;
      if (state.view === 'browse') renderBrowse(); else if (state.view === 'study') renderStudy(); else if (quiet) render();
      if (quiet || state.view === 'browse') window.scrollTo(0, y);
    }
    function chipHtml() { return h`<span class="save-chip" data-state="${Saver.state()}" role="status">${esc(Saver.text())}</span>`; }
    function bindChip(root) { const c = root.querySelector('.save-chip'); if (c) c.onclick = () => Saver.flush(true); }
    function refreshChips() { document.querySelectorAll('.save-chip').forEach(el => { el.dataset.state = Saver.state(); el.textContent = Saver.text(); }); }
    return { add, count, persist, deleteCard, chipHtml, bindChip, refreshChips, onChange: (fn) => listeners.push(fn), rerender };
  })();

  // ------------------------------------------------------------ saving to GitHub
  // Queued ops are committed to docs/decks/<file>.json in the repo the site is served from, using
  // the token this device got from Matt's setup link. Batches go out a few seconds after the last
  // edit, when the page is hidden, and when the connection comes back.
  const Saver = (() => {
    let status = 'idle', timer = null, retryTimer = null, busy = false, savedOnce = false;
    function repo() {
      if (/^(localhost|127\.0\.0\.1|\[::1\])$/.test(location.hostname)) {
        const dev = loadJSON('nf.gh.dev'); // local testing only, e.g. tests/mock_github.py
        return dev && dev.api ? { branch: 'main', ...dev } : null;
      }
      const m = location.hostname.match(/^([a-z0-9-]+)\.github\.io$/i); const seg = location.pathname.split('/').filter(Boolean)[0];
      return m && seg ? { api: 'https://api.github.com', owner: m[1], repo: seg, branch: 'main' } : null;
    }
    const token = () => (loadJSON(GH_KEY) || {}).token || null;
    const canSave = () => !!(repo() && token());
    function set(st) { status = st; Edits.refreshChips(); if (state.view === 'sync' && !Editor.isOpen()) renderSync(); }
    function stateName() {
      if (busy) return 'saving';
      const n = Edits.count();
      if (!n) return savedOnce ? 'saved' : 'idle';
      if (!canSave()) return 'local';
      return ['offline', 'auth', 'error'].includes(status) ? status : 'pending';
    }
    function text() {
      const n = Edits.count(); const c = `${n} change${n === 1 ? '' : 's'}`;
      return {
        saving: 'Saving…', saved: 'All changes saved', idle: 'No unsaved changes',
        local: `${c} on this device only`, pending: `${c} waiting to save`, offline: `Offline · ${c} waiting`,
        auth: 'Saving paused · ask Matt for a new link', error: 'Couldn’t save · will retry',
      }[stateName()];
    }
    function schedule(ms = 6000) {
      clearTimeout(timer);
      if (Edits.count() && canSave()) timer = setTimeout(() => flush(), ms);
      Edits.refreshChips();
    }
    function retry(ms) { clearTimeout(retryTimer); retryTimer = setTimeout(() => flush(), ms); }
    async function flush(manual) {
      clearTimeout(timer);
      if (busy) return;
      if (!Edits.count()) { if (manual) toast('Nothing to save'); return; }
      const r = repo(), t = token();
      if (!r || !t) { if (manual) toast(r ? 'This device can’t save yet. Open the setup link Matt sent you.' : 'Saving isn’t available on this site'); set('local'); return; }
      busy = true; Edits.refreshChips();
      try {
        for (const key of Object.keys(state.pending)) {
          const ops = (state.pending[key] || []).slice(); if (!ops.length) continue;
          const entry = state.index && state.index.get(key); if (!entry) continue;
          const before = JSON.stringify((state.decks.find(x => x.key === key) || {}).sections);
          const title = (state.decks.find(x => x.key === key) || {}).title || key;
          const res = await NFCore.saveToGitHub({
            fetch: window.fetch.bind(window), api: r.api, owner: r.owner, repo: r.repo, branch: r.branch, token: t,
            path: 'docs/decks/' + entry.file, ops, message: `App edit (${title}): ${NFCore.describeOps(ops)}`,
          });
          const done = new Set(ops.map(o => o.n));
          state.pending[key] = (state.pending[key] || []).filter(o => !done.has(o.n));
          Edits.persist();
          const saved = loadJSON(SAVED_KEY) || {}; saved[key] = res.deck; saveJSON(SAVED_KEY, saved);
          state.base = state.base.map(x => (x.key === key ? res.deck : x));
          rebuild();
          if (res.skipped.length) toast(`${res.skipped.length} change${res.skipped.length === 1 ? '' : 's'} couldn’t be applied: the card was changed or deleted on another device`);
          // show changes that came from the other device
          if (JSON.stringify((state.decks.find(x => x.key === key) || {}).sections) !== before && !Editor.isOpen() && ['browse', 'home', 'stats'].includes(state.view)) Edits.rerender(true);
        }
        savedOnce = true; busy = false; set(Edits.count() ? 'pending' : 'saved');
        if (Edits.count()) schedule(1000); // edits made while saving
        else if (manual) toast('All changes saved');
      } catch (e) {
        busy = false;
        const kind = e.kind || 'error';
        if (kind === 'auth') { set('auth'); if (manual) toast('GitHub refused this device’s key. Ask Matt for a new setup link.'); }
        else if (kind === 'offline') { set('offline'); retry(30000); }
        else { set('error'); retry(kind === 'conflict' ? 5000 : 60000); console.warn('Save failed:', e.message); }
      }
    }
    // checks a token can write to the repo: true, false, or 'offline'
    async function verify(tok) {
      const r = repo(); if (!r) return false;
      try {
        const res = await fetch(`${r.api}/repos/${r.owner}/${r.repo}`, { cache: 'no-store', headers: { Accept: 'application/vnd.github+json', Authorization: 'Bearer ' + tok } });
        if (!res.ok) return false;
        const j = await res.json(); return !!(j.permissions && j.permissions.push);
      } catch { return 'offline'; }
    }
    async function useSetupToken(raw) {
      let tok = ''; try { tok = decodeURIComponent(raw || '').trim(); } catch {}
      if (!tok) return;
      if (!repo()) { toast('Setup links only work on the flashcards website'); return; }
      const ok = await verify(tok);
      if (ok === true) { saveJSON(GH_KEY, { token: tok, at: Date.now() }); status = 'idle'; toast('Editing is turned on for this device'); schedule(500); if (state.view === 'sync') renderSync(); }
      else toast(ok === 'offline' ? 'You’re offline, so the setup link couldn’t be checked. Open it again when you’re online.' : 'This setup link didn’t work. Ask Matt for a new one.');
    }
    function forget() { saveJSON(GH_KEY, null); status = 'idle'; Edits.refreshChips(); }
    Edits.onChange(() => schedule());
    window.addEventListener('online', () => { if (Edits.count()) flush(); });
    document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden' && Edits.count() && canSave()) flush(); });
    return { state: stateName, text, schedule, flush, verify, useSetupToken, forget, canSave, hasToken: () => !!token(), repo };
  })();


  // ------------------------------------------------------------ sheets (simple action menus)
  function openSheet(title, bodyHtml, onAction) {
    closeSheet();
    const el = document.createElement('div'); el.className = 'gl-pop'; el.id = 'sheet';
    el.innerHTML = h`<div class="gl-sheet sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><button class="gl-x" data-act="sheet-close" aria-label="Close">×</button><div class="gl-term">${esc(title)}</div>${bodyHtml}</div>`;
    el.addEventListener('click', (e) => {
      if (e.target === el || e.target.closest('[data-act=sheet-close]')) { closeSheet(); return; }
      const b = e.target.closest('[data-a]'); if (b && !b.disabled) { closeSheet(); onAction(b.dataset.a, b.dataset.v); }
    });
    document.body.appendChild(el);
    el.querySelector('.gl-x').focus({ preventScroll: true });
  }
  function closeSheet() { const el = document.getElementById('sheet'); if (el) { el.remove(); return true; } return false; }

  // ------------------------------------------------------------ regrouping (move cards, manage sections and units)
  const Regroup = (() => {
    const deckOf = (key) => state.decks.find(x => x.key === key);
    const ask = (q, v) => { const r = prompt(q, v || ''); return r == null ? null : r.trim(); };
    const secTitle = (d, s) => (s.group && s.group !== s.name ? s.group + ' › ' : '') + sLabel(d, s);

    function moveCard(deckKey, id) {
      const d = deckOf(deckKey); const c = state.cards.get(id); if (!d || !c) return;
      const sec = d.sections.find(x => sKey(x) === c.sectionKey); const i = sec.cards.findIndex(x => x.id === id);
      const body = h`<div class="sheet-sub">${esc(c.prompt.length > 70 ? c.prompt.slice(0, 70) + '…' : c.prompt)}</div>
        <div class="lbl">Within ${esc(sLabel(d, sec))}</div>
        <div class="row"><button class="btn small" data-a="up" ${i === 0 ? 'disabled' : ''}>↑ Move up</button><button class="btn small" data-a="down" ${i === sec.cards.length - 1 ? 'disabled' : ''}>↓ Move down</button>
          <button class="btn small" data-a="top" ${i === 0 ? 'disabled' : ''}>⤒ To top</button></div>
        <div class="lbl">Move to another section</div>
        ${groupsOf(d).map(G => h`${G.name ? h`<div class="sheet-grp">${esc(G.name)}</div>` : ''}<div class="sheet-list">${G.secs.map(x => h`<button class="sheet-item" data-a="to" data-v="${esc(sKey(x))}" ${x === sec ? 'disabled' : ''}>${esc(sLabel(d, x))}<span class="cnt">${x === sec ? 'here' : x.cards.length}</span></button>`).join('')}</div>`).join('')}`;
      openSheet('Move card', body, (a, v) => {
        if (a === 'up') Edits.add(deckKey, { t: 'move', id, sec: c.sectionKey, before: sec.cards[i - 1].id });
        else if (a === 'down') Edits.add(deckKey, { t: 'move', id, sec: c.sectionKey, before: sec.cards[i + 2] ? sec.cards[i + 2].id : null });
        else if (a === 'top') Edits.add(deckKey, { t: 'move', id, sec: c.sectionKey, before: sec.cards[0].id });
        else if (a === 'to') { Edits.add(deckKey, { t: 'move', id, sec: v, before: null }); const to = d.sections.find(x => sKey(x) === v); toast('Moved to ' + (to ? sLabel(d, to) : v)); }
        Edits.rerender();
      });
    }

    function sectionMenu(deckKey, key) {
      const d = deckOf(deckKey); const sec = d && d.sections.find(x => sKey(x) === key); if (!sec) return;
      const same = d.sections.filter(x => (x.group || '') === (sec.group || ''));
      const j = same.indexOf(sec);
      const groups = groupsOf(d); const gi = groups.findIndex(G => G.name === (sec.group || ''));
      const body = h`<div class="sheet-sub">${esc(secTitle(d, sec))} · ${sec.cards.length} card${sec.cards.length === 1 ? '' : 's'}</div>
        <div class="sheet-list">
          <button class="sheet-item" data-a="rename">Rename section</button>
          <button class="sheet-item" data-a="up" ${j === 0 ? 'disabled' : ''}>Move section up</button>
          <button class="sheet-item" data-a="down" ${j === same.length - 1 ? 'disabled' : ''}>Move section down</button>
          <button class="sheet-item" data-a="add">Add a section below</button>
          ${sec.group ? h`<button class="sheet-item" data-a="rgroup">Rename unit “${esc(sec.group)}”</button>
            <button class="sheet-item" data-a="gup" ${gi <= 0 ? 'disabled' : ''}>Move unit up</button>
            <button class="sheet-item" data-a="gdown" ${gi === groups.length - 1 ? 'disabled' : ''}>Move unit down</button>` : ''}
          <button class="sheet-item danger" data-a="del" ${sec.cards.length ? 'disabled' : ''}>Delete section${sec.cards.length ? ' (move or delete its cards first)' : ''}</button>
        </div>`;
      openSheet('Section', body, (a) => {
        if (a === 'rename') { const n = ask('New name for this section:', sec.name); if (n && n !== sec.name) add(deckKey, { t: 'renameSec', sec: key, name: n }, 'A section with that name already exists in this unit'); }
        else if (a === 'up') add(deckKey, { t: 'moveSec', sec: key, before: sKey(same[j - 1]) });
        else if (a === 'down') { const after = d.sections[d.sections.indexOf(same[j + 1]) + 1]; add(deckKey, { t: 'moveSec', sec: key, before: after ? sKey(after) : null }); }
        else if (a === 'add') addSection(deckKey, sec);
        else if (a === 'rgroup') { const n = ask('New name for this unit:', sec.group); if (n && n !== sec.group) add(deckKey, { t: 'renameGroup', group: sec.group, to: n }, 'A unit with that name already exists'); }
        else if (a === 'gup' || a === 'gdown') moveUnit(deckKey, d, groups, gi, a === 'gup' ? -1 : 1);
        else if (a === 'del') { if (confirm(`Delete the empty section “${sec.name}”?`)) add(deckKey, { t: 'delSec', sec: key }); }
      });
    }
    // all of a unit's sections go before the first section of the target unit
    function moveUnit(deckKey, d, groups, gi, dir) {
      const target = dir < 0 ? groups[gi - 1] : groups[gi + 2];
      const before = target ? sKey(target.secs[0]) : null;
      Edits.add(deckKey, ...groups[gi].secs.map(x => ({ t: 'moveSec', sec: sKey(x), before })));
      Edits.rerender();
    }
    // apply one op; tell the user if it didn't apply (name clash etc.)
    function add(deckKey, op, failMsg) {
      const d = deckOf(deckKey);
      if (!NFCore.applyOps(d, [op]).skipped.length) { Edits.add(deckKey, op); Edits.rerender(); }
      else toast(failMsg || 'That change isn’t possible');
    }
    function addSection(deckKey, afterSec) {
      const n = ask('Name of the new section:'); if (!n) return;
      const group = afterSec ? afterSec.group || '' : '';
      add(deckKey, { t: 'addSec', group, name: n, after: afterSec ? sKey(afterSec) : null }, 'A section with that name already exists here');
    }
    function addUnit(deckKey) {
      const g = ask('Name of the new unit:'); if (!g) return;
      if (deckOf(deckKey).sections.some(x => x.group === g)) { toast('A unit with that name already exists'); return; }
      const n = ask('Name of its first section:', g); if (!n) return;
      add(deckKey, { t: 'addSec', group: g, name: n, after: null });
    }
    return { moveCard, sectionMenu, addSection, addUnit };
  })();

  // ------------------------------------------------------------ card editor
  const Editor = (() => {
    const HIGHLIGHTS = [['#00ffff', 'Cyan'], ['#ffff00', 'Yellow'], ['#00ff00', 'Green'], ['#ff9900', 'Orange']];
    const COLORS = [['#ff0000', 'Red'], ['#ff00ff', 'Magenta'], ['#0000ff', 'Blue']];
    let el = null, lastField = null, initial = null, ctx = null;

    function open(opts) {
      close(true);
      const d = state.decks.find(x => x.key === opts.deckKey); if (!d) return;
      const card = opts.cardId ? state.cards.get(opts.cardId) : null;
      if (opts.cardId && !card) { toast('That card no longer exists'); return; }
      const sec = card ? d.sections.find(x => sKey(x) === card.sectionKey) : d.sections.find(x => sKey(x) === opts.sec);
      ctx = { deckKey: d.key, cardId: opts.cardId || null, sec: sec ? sKey(sec) : opts.sec, after: opts.after || null };
      el = document.createElement('div'); el.className = 'ed-pop'; el.id = 'editor';
      el.innerHTML = h`<div class="ed-sheet" role="dialog" aria-modal="true" aria-label="${card ? 'Edit card' : 'New card'}">
        <div class="ed-head"><button class="btn small ghost" data-act="ed-cancel">Cancel</button><b>${card ? 'Edit card' : 'New card'}</b><button class="btn small primary" data-act="ed-save">Save</button></div>
        <div class="ed-tools" role="toolbar" aria-label="Formatting">
          <button data-cmd="bold" aria-label="Bold"><b>B</b></button><button data-cmd="italic" aria-label="Italic"><i>I</i></button><button data-cmd="underline" aria-label="Underline"><u>U</u></button><button data-cmd="strikeThrough" aria-label="Strikethrough"><s>S</s></button>
          <span class="ed-sep"></span>
          <button data-cmd="insertUnorderedList" aria-label="Bulleted list">•≡</button><button data-cmd="insertOrderedList" aria-label="Numbered list">1≡</button><button data-cmd="outdent" aria-label="Decrease indent">⇤</button><button data-cmd="indent" aria-label="Increase indent">⇥</button>
          <span class="ed-sep"></span>
          ${HIGHLIGHTS.map(([c, n]) => h`<button data-hl="${c}" aria-label="${n} highlight" title="${n} highlight"><span class="sw" style="background:${c}"></span></button>`).join('')}<button data-hl="transparent" aria-label="Remove highlight" title="Remove highlight"><span class="sw none"></span></button>
          <span class="ed-sep"></span>
          ${COLORS.map(([c, n]) => h`<button data-fc="${c}" aria-label="${n} text" title="${n} text"><span class="fc" style="color:${c}">A</span></button>`).join('')}<button data-fc="#1b1f2a" aria-label="Default text colour" title="Default text colour"><span class="fc">A</span></button>
          <span class="ed-sep"></span>
          <button data-cmd="removeFormat" aria-label="Clear formatting" title="Clear formatting">⌫ᶠ</button>
        </div>
        <div class="ed-body">
          <label class="lbl" for="ed-prompt">Prompt (front)</label>
          <div class="ed-field" id="ed-prompt" contenteditable="true" role="textbox" aria-multiline="true">${card ? (card.promptHtml || esc(card.prompt)) : ''}</div>
          <label class="lbl" for="ed-answer">Answer (back)</label>
          <div class="ed-field a" id="ed-answer" contenteditable="true" role="textbox" aria-multiline="true">${card ? card.answerHtml : ''}</div>
          <label class="lbl" for="ed-label">Label (optional, small tag on the card)</label>
          <input id="ed-label" type="text" value="${esc(card ? card.label || '' : '')}" autocomplete="off">
          <p class="hint">${esc(d.title)} · ${esc(sec ? sLabel(d, sec) + (sec.group && sec.group !== sec.name ? ' (' + sec.group + ')' : '') : '')}. Pasting from Google Docs keeps bold, italics, colours and highlights.</p>
        </div></div>`;
      document.body.appendChild(el);
      document.body.classList.add('editing');
      try { document.execCommand('defaultParagraphSeparator', false, 'p'); } catch {}
      const fields = el.querySelectorAll('.ed-field');
      fields.forEach(f => {
        f.addEventListener('focus', () => { lastField = f; });
        f.addEventListener('paste', onPaste);
      });
      lastField = fields[0];
      initial = snapshot();
      el.querySelector('.ed-tools').addEventListener('pointerdown', (e) => { if (e.target.closest('button')) e.preventDefault(); }); // keep the text selection
      el.querySelector('.ed-tools').addEventListener('click', onTool);
      el.querySelector('[data-act=ed-cancel]').onclick = () => close();
      el.querySelector('[data-act=ed-save]').onclick = save;
      el.addEventListener('keydown', (e) => { if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') { e.preventDefault(); save(); } });
      (card ? fields[1] : fields[0]).focus({ preventScroll: true });
    }
    function snapshot() { return [el.querySelector('#ed-prompt').innerHTML, el.querySelector('#ed-answer').innerHTML, el.querySelector('#ed-label').value]; }
    function dirty() { return el && snapshot().some((v, i) => v !== initial[i]); }
    function onPaste(e) {
      const html = e.clipboardData && e.clipboardData.getData('text/html');
      const text = e.clipboardData && e.clipboardData.getData('text/plain');
      e.preventDefault();
      const clean = html ? NFCore.sanitizeHtml(html) : esc(text || '').replace(/\r?\n/g, '<br>');
      document.execCommand('insertHTML', false, clean);
    }
    function onTool(e) {
      const b = e.target.closest('button'); if (!b || !lastField) return;
      lastField.focus({ preventScroll: true });
      const css = (on) => { try { document.execCommand('styleWithCSS', false, on); } catch {} };
      if (b.dataset.cmd) { css(false); document.execCommand(b.dataset.cmd, false, null); if (b.dataset.cmd === 'removeFormat') { css(true); document.execCommand('hiliteColor', false, 'transparent'); } }
      else if (b.dataset.hl) { css(true); if (!document.execCommand('hiliteColor', false, b.dataset.hl)) document.execCommand('backColor', false, b.dataset.hl); }
      else if (b.dataset.fc) { css(true); document.execCommand('foreColor', false, b.dataset.fc); }
    }
    function save() {
      if (!el) return;
      const promptHtml = NFCore.sanitizeHtml(el.querySelector('#ed-prompt').innerHTML);
      const answerHtml = NFCore.sanitizeHtml(el.querySelector('#ed-answer').innerHTML);
      const label = el.querySelector('#ed-label').value.trim();
      if (!NFCore.htmlToText(promptHtml) && !/<img/.test(promptHtml)) { toast('Add a prompt first'); el.querySelector('#ed-prompt').focus(); return; }
      if (ctx.cardId) {
        const c = state.cards.get(ctx.cardId);
        const op = { t: 'edit', id: ctx.cardId };
        if (promptHtml !== NFCore.sanitizeHtml(c.promptHtml || esc(c.prompt))) op.promptHtml = promptHtml;
        if (answerHtml !== NFCore.sanitizeHtml(c.answerHtml)) op.answerHtml = answerHtml;
        if (label !== (c.label || '')) op.label = label;
        if (Object.keys(op).length > 2) { Edits.add(ctx.deckKey, op); toast('Card updated'); }
      } else {
        const id = NFCore.newId(n => crypto.getRandomValues(new Uint8Array(n)));
        const d = state.decks.find(x => x.key === ctx.deckKey); const sec = d && d.sections.find(x => sKey(x) === ctx.sec);
        Edits.add(ctx.deckKey, { t: 'add', id, sec: ctx.sec, secName: sec ? sec.name : ctx.sec, group: sec ? sec.group || '' : '', before: null, promptHtml, answerHtml, label });
        state.browseOpen.add(id);
        toast('Card added');
      }
      close(true);
      Edits.rerender();
    }
    function close(force) {
      if (!el) return true;
      if (!force && dirty() && !confirm('Discard your changes to this card?')) return false;
      el.remove(); el = null; lastField = null; ctx = null;
      document.body.classList.remove('editing');
      return true;
    }
    return { open, close, isOpen: () => !!el };
  })();

  // ------------------------------------------------------------ glossary
  // Terms from docs/glossary/<name>.json are underlined in card text for the tests listed in
  // docs/glossary/index.json; tapping one opens its definition. Matching is whole-word with an
  // optional plural s/es, longest name first, first occurrence per term per card side.
  // All-caps names (acronyms like TD, EPS) must match case exactly.
  const Glossary = (() => {
    let index = null;                 // [{ name, title, file, decks }]
    const loaded = new Map();         // name -> { terms, byName, rx } | Promise
    const isAcronym = (n) => /^[A-Za-z0-9&-]{2,10}$/.test(n) && (n.match(/[A-Z]/g) || []).length >= 2;
    const norm = (t) => t.replace(/[\u2018\u2019]/g, "'").toLowerCase();
    const escRx = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/'/g, "['\u2019]");

    async function init() {
      try { const r = await fetch('glossary/index.json', { cache: 'no-cache' }); index = r.ok ? (await r.json()).glossaries || [] : []; }
      catch { index = []; }
    }
    const forDeck = (key) => (index || []).find(g => (g.decks || []).includes(key)) || null;
    const enabled = () => state.prefs.glossary !== false;
    function has(key) { return !!forDeck(key); }

    function compile(data) {
      const byName = new Map();       // normalised name -> [{ i, exact }]
      data.terms.forEach((t, i) => t.names.forEach(n => {
        const k = norm(n); if (!byName.has(k)) byName.set(k, []);
        byName.get(k).push({ i, exact: isAcronym(n) ? n : null });
      }));
      const alts = [...byName.keys()].sort((a, b) => b.length - a.length).map(escRx);
      const rx = new RegExp(`(^|[^\\p{L}\\p{N}])((?:${alts.join('|')})(?:s|es)?)(?=$|[^\\p{L}\\p{N}])`, 'giu');
      return { terms: data.terms, byName, rx };
    }
    function get(g) {
      const v = loaded.get(g.name);
      if (v && !(v instanceof Promise)) return v;
      if (!v) loaded.set(g.name, fetch('glossary/' + g.file, { cache: 'no-cache' }).then(r => r.json()).then(d => { loaded.set(g.name, compile(d)); decorate(); })
        .catch(() => loaded.delete(g.name)));
      return null;
    }
    // which entries a matched string refers to (handles plural endings and exact-case acronyms)
    function lookup(G, text) {
      const k = norm(text);
      for (const cand of [k, k.replace(/es$/, ''), k.replace(/s$/, '')]) {
        const hits = (G.byName.get(cand) || []).filter(h => !h.exact || text === h.exact || text === h.exact + 's' || text.replace(/s$/, '') === h.exact);
        if (hits.length) return [...new Set(hits.map(h => h.i))];
      }
      return null;
    }

    // underline terms inside root; avoidText: skip a match covering most of this text (front-of-card spoiler guard)
    function apply(root, G, avoidText) {
      if (!root || root.dataset.gl) return; root.dataset.gl = '1';
      const avoid = avoidText ? avoidText.replace(/[^\p{L}\p{N}]+/gu, '') : '';
      const seen = new Set();
      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
        acceptNode: (n) => n.nodeValue.trim() && !n.parentElement.closest('.gl, a, button, input, textarea') ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT,
      });
      const nodes = []; while (walker.nextNode()) nodes.push(walker.currentNode);
      for (const node of nodes) {
        const text = node.nodeValue; let m, last = 0; const frag = document.createDocumentFragment(); let changed = false;
        G.rx.lastIndex = 0;
        while ((m = G.rx.exec(text))) {
          const word = m[2]; const ids = lookup(G, word);
          const start = m.index + m[1].length;
          if (!ids || ids.every(i => seen.has(i))) continue;
          if (avoid && word.replace(/[^\p{L}\p{N}]+/gu, '').length >= 0.6 * avoid.length) continue;
          ids.forEach(i => seen.add(i));
          frag.append(text.slice(last, start));
          const span = document.createElement('span'); span.className = 'gl'; span.textContent = word;
          span.dataset.g = ids.join(','); span.setAttribute('role', 'button'); span.tabIndex = 0;
          span.setAttribute('aria-label', word + ', show definition');
          frag.append(span); last = start + word.length; changed = true;
        }
        if (changed) { frag.append(text.slice(last)); node.replaceWith(frag); }
      }
    }

    // underline terms in whatever the current view shows (called after each render and when a glossary loads)
    function decorate() {
      if (!index || !enabled()) return;
      if (state.view === 'study') {
        const $card = $app.querySelector('#card'); if (!$card) return;
        const g = forDeck($card.dataset.deck); if (!g) return; const G = get(g); if (!G) return;
        const front = $card.querySelector('.front .prompt');
        if (front) apply(front, G, front.textContent);
        else { apply($card.querySelector('.back .q'), G); apply($card.querySelector('.back .a'), G); }
      } else if (state.view === 'browse') {
        const g = forDeck(deck().key); if (!g) return; const G = get(g); if (!G) return;
        $app.querySelectorAll('.b-card').forEach(el => { apply(el.querySelector('summary .p'), G); apply(el.querySelector('.ans'), G); });
      }
    }

    function open(span) {
      const $card = span.closest('#card');
      const g = forDeck($card ? $card.dataset.deck : deck().key); const G = g && loaded.get(g.name);
      if (!G || G instanceof Promise) return;
      close();
      const items = span.dataset.g.split(',').map(i => G.terms[+i]);
      const el = document.createElement('div'); el.className = 'gl-pop'; el.id = 'gl-pop';
      el.innerHTML = h`<div class="gl-sheet" role="dialog" aria-modal="true" aria-label="Definition">
          <button class="gl-x" data-act="gl-close" aria-label="Close">×</button>
          ${items.map(t => h`<div class="gl-item"><div class="gl-term">${esc(t.term)}</div><div class="gl-def">${t.html}</div>${t.source ? h`<div class="gl-src">${esc(t.source)}</div>` : ''}</div>`).join('')}
          <div class="gl-foot">${esc(g.title || 'Glossary')} · <button class="link" data-act="gl-off">Turn off underlines</button></div>
        </div>`;
      el.addEventListener('click', (e) => {
        if (e.target === el || e.target.closest('[data-act=gl-close]')) { close(); return; }
        if (e.target.closest('[data-act=gl-off]')) { state.prefs.glossary = false; savePrefs(); close(); render(); toast('Glossary underlines off. Turn them back on from Home.'); }
      });
      document.body.appendChild(el);
      el.querySelector('.gl-x').focus({ preventScroll: true });
    }
    function close() { const el = document.getElementById('gl-pop'); if (el) el.remove(); }
    const isOpen = () => !!document.getElementById('gl-pop');

    // capture phase: a tap on a term must not also flip the card or open/close a Browse card
    document.addEventListener('click', (e) => {
      const span = e.target.closest && e.target.closest('.gl'); if (!span) return;
      e.preventDefault(); e.stopPropagation(); open(span);
    }, true);
    document.addEventListener('keydown', (e) => {
      const span = e.target.closest && e.target.closest('.gl');
      if (span && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); e.stopPropagation(); open(span); }
    }, true);

    return { init, has, decorate, close, isOpen, enabled };
  })();

  // ------------------------------------------------------------ boot
  (async () => {
    try { await Promise.all([loadDecks(), Glossary.init()]); }
    catch (e) { $app.innerHTML = '<p class="empty">Could not load the cards.<br>Check your connection and reload. (Developer: run <code>python3 tools/import_doc.py &lt;doc url&gt;</code>.)</p>'; return; }
    if (location.hash.startsWith('#sync=')) { await handleIncomingSync(location.hash.slice(6)); return; }
    const v = (location.hash || '#home').slice(1) || 'home';
    state.view = ['home', 'stats', 'browse', 'sync'].includes(v) ? v : (v === 'study' && state.session ? 'study' : 'home');
    render();
    if (setupToken) { const raw = setupToken; setupToken = null; Saver.useSetupToken(raw); }
    else if (Edits.count()) Saver.schedule(2000);
  })();
})();
